CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role = _role
  )
$function$
CREATE OR REPLACE FUNCTION public.core_est_proprietaire(p_apprenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.apprenants a WHERE a.id = p_apprenant_id AND a.auth_user_id = auth.uid());
$function$
CREATE OR REPLACE FUNCTION public.core_assert_session_owner(p_apprenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  mine uuid;
BEGIN
  IF uid IS NULL THEN
    RETURN; -- contexte serveur / service_role : autres invariants applicables
  END IF;

  SELECT a.id INTO mine FROM public.apprenants a WHERE a.auth_user_id = uid LIMIT 1;

  IF mine IS NULL THEN
    RETURN; -- session non apprenante (formateur / admin) : domaine correction
  END IF;

  IF mine IS DISTINCT FROM p_apprenant_id THEN
    RAISE EXCEPTION 'SESSION_NON_AUTORISEE: la session authentifiee (apprenant %) n''est pas autorisee pour la tentative de l''apprenant %.',
      mine, p_apprenant_id
      USING ERRCODE = 'P0477';
  END IF;
END;
$function$
CREATE FUNCTION public.core_identite_api_verifiee() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE claims jsonb; sub text; BEGIN IF session_user<>'authenticator' OR coalesce(current_setting('role',true),'none')<>'authenticated' THEN RETURN NULL; END IF; claims:=nullif(current_setting('request.jwt.claims',true),'')::jsonb; IF claims IS NULL OR claims->>'role' IS DISTINCT FROM 'authenticated' THEN RETURN NULL; END IF; sub:=claims->>'sub'; IF sub IS NULL OR sub !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN NULL; END IF; IF auth.uid() IS DISTINCT FROM sub::uuid OR auth.role() IS DISTINCT FROM 'authenticated' THEN RETURN NULL; END IF; RETURN sub::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END $$;
CREATE FUNCTION public.core_contexte_correction_autorise() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ SELECT CASE WHEN session_user='service_role' AND coalesce(current_setting('role',true),'none') IN('none','service_role') THEN true WHEN session_user='authenticator' AND current_setting('role',true)='service_role' THEN true ELSE coalesce(public.has_role(public.core_identite_api_verifiee(),'admin'),false) END $$;
CREATE OR REPLACE FUNCTION public.core_contexte_tentative_autorise(p_apprenant_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ SELECT public.core_contexte_correction_autorise() OR (p_apprenant_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.apprenants a WHERE a.id=p_apprenant_id AND a.auth_user_id=public.core_identite_api_verifiee())) $$;
CREATE FUNCTION public.core_snapshot_question_ids(p_node jsonb) RETURNS SETOF text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE k text;v jsonb; BEGIN IF p_node IS NULL THEN RETURN; END IF; IF jsonb_typeof(p_node)='array' THEN FOR v IN SELECT value FROM jsonb_array_elements(p_node) LOOP RETURN QUERY SELECT * FROM public.core_snapshot_question_ids(v); END LOOP; ELSIF jsonb_typeof(p_node)='object' THEN FOR k,v IN SELECT key,value FROM jsonb_each(p_node) LOOP IF k IN('id','question_id','questionId') AND jsonb_typeof(v) IN('string','number') THEN RETURN NEXT(v#>>'{}'); ELSE RETURN QUERY SELECT * FROM public.core_snapshot_question_ids(v); END IF; END LOOP; END IF; RETURN; END $$;
CREATE FUNCTION public.core_snapshot_has_question(p_snapshot jsonb,p_question_id text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.core_snapshot_question_ids(p_snapshot) qid WHERE qid=p_question_id) $$;
CREATE OR REPLACE FUNCTION public.set_next_quiz_tentative()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_next integer;
BEGIN
  -- Only auto-assign when tentative is at default (1) AND a row already exists for the same key
  IF NEW.tentative IS NULL OR NEW.tentative = 1 THEN
    SELECT COALESCE(MAX(tentative), 0) + 1 INTO v_next
    FROM public.apprenant_quiz_results
    WHERE apprenant_id = NEW.apprenant_id
      AND quiz_id = NEW.quiz_id
      AND COALESCE(matiere_id, '') = COALESCE(NEW.matiere_id, '');
    IF v_next > 1 THEN
      NEW.tentative := v_next;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.core_enforce_qrc_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  att public.exam_attempts_v2%ROWTYPE;
BEGIN
  SELECT * INTO att FROM public.exam_attempts_v2 WHERE attempt_id = NEW.attempt_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ATTEMPT_INTROUVABLE: tentative % inexistante.', NEW.attempt_id
      USING ERRCODE = 'P0477';
  END IF;

  IF NEW.apprenant_id IS DISTINCT FROM att.apprenant_id THEN
    RAISE EXCEPTION 'QRC_OWNERSHIP: la QRC (apprenant %) n''appartient pas au proprietaire de la tentative (apprenant %).',
      NEW.apprenant_id, att.apprenant_id
      USING ERRCODE = 'P0477';
  END IF;

  IF TG_OP = 'INSERT' THEN
    PERFORM public.core_assert_session_owner(att.apprenant_id);

    IF att.etat <> 'en_cours' THEN
      RAISE EXCEPTION 'ATTEMPT_CLOSED: la tentative % est % : aucune QRC ne peut plus y etre creee.', att.attempt_id, att.etat
        USING ERRCODE = 'P0478';
    END IF;

    IF NOT public.core_snapshot_has_question(att.snapshot, NEW.question_id) THEN
      RAISE EXCEPTION 'QUESTION_HORS_SNAPSHOT: la question % ne fait pas partie du snapshot de la tentative % (examen %).',
        NEW.question_id, att.attempt_id, att.exam_id
        USING ERRCODE = 'P0479';
    END IF;
  ELSE
    -- Correction formateur autorisee apres la fin de la tentative,
    -- MAIS la reponse originale de l'eleve reste figee.
    IF NEW.reponse IS DISTINCT FROM OLD.reponse THEN
      RAISE EXCEPTION 'QRC_REPONSE_ELEVE_FIGEE: la reponse originale de l''eleve ne peut pas etre modifiee par une correction (%).',
        OLD.qrc_instance_id
        USING ERRCODE = 'P0480';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.enforce_exam_retake_delay()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exam text;
  v_tent integer;
  v_already_started boolean;
  v_last timestamptz;
  v_auth uuid;
  v_total_matieres integer;
  v_matieres_prec integer;
BEGIN
  IF COALESCE(NEW.exercice_type, '') <> 'examen_blanc' THEN
    RETURN NEW;
  END IF;

  v_exam := split_part(COALESCE(NEW.exercice_id, ''), '__', 1);
  IF v_exam = '' THEN
    RETURN NEW;
  END IF;

  v_tent := GREATEST(
    COALESCE(NULLIF(substring(COALESCE(NEW.exercice_id, '') FROM '_t([0-9]+)$'), '')::int, 1),
    COALESCE(NEW.tentative, 1)
  );

  IF v_tent <= 1 THEN
    RETURN NEW;
  END IF;

  -- Tentative déjà ouverte (une autre matière du même passage existe) : jamais bloquée
  SELECT EXISTS (
    SELECT 1 FROM public.reponses_apprenants r
    WHERE r.apprenant_id = NEW.apprenant_id
      AND r.exercice_type = 'examen_blanc'
      AND split_part(COALESCE(r.exercice_id, ''), '__', 1) = v_exam
      AND GREATEST(
            COALESCE(NULLIF(substring(COALESCE(r.exercice_id, '') FROM '_t([0-9]+)$'), '')::int, 1),
            COALESCE(r.tentative, 1)
          ) >= v_tent
  ) INTO v_already_started;

  IF v_already_started THEN
    RETURN NEW;
  END IF;

  -- Nombre de matières que comporte cet examen (observé en base, lecture seule)
  SELECT COUNT(DISTINCT split_part(COALESCE(r.exercice_id, ''), '__', 2))
    INTO v_total_matieres
  FROM public.reponses_apprenants r
  WHERE r.exercice_type = 'examen_blanc'
    AND split_part(COALESCE(r.exercice_id, ''), '__', 1) = v_exam
    AND split_part(COALESCE(r.exercice_id, ''), '__', 2) <> '';

  -- Matières réellement finalisées par l'apprenant sur les tentatives précédentes
  SELECT COUNT(DISTINCT split_part(COALESCE(r.exercice_id, ''), '__', 2))
    INTO v_matieres_prec
  FROM public.reponses_apprenants r
  WHERE r.apprenant_id = NEW.apprenant_id
    AND r.exercice_type = 'examen_blanc'
    AND split_part(COALESCE(r.exercice_id, ''), '__', 1) = v_exam
    AND r.completed IS TRUE
    AND split_part(COALESCE(r.exercice_id, ''), '__', 2) <> '';

  -- Tentative précédente incomplète : l'apprenant est encore dans son passage, aucun délai
  IF COALESCE(v_total_matieres, 0) = 0
     OR COALESCE(v_matieres_prec, 0) < v_total_matieres THEN
    RETURN NEW;
  END IF;

  SELECT MAX(COALESCE(r.submitted_at, r.updated_at, r.created_at))
    INTO v_last
  FROM public.reponses_apprenants r
  WHERE r.apprenant_id = NEW.apprenant_id
    AND r.exercice_type = 'examen_blanc'
    AND split_part(COALESCE(r.exercice_id, ''), '__', 1) = v_exam
    AND r.completed IS TRUE;

  IF v_last IS NOT NULL AND now() < v_last + interval '48 hours' THEN
    SELECT a.id INTO v_auth
    FROM public.exam_retake_authorizations a
    WHERE a.apprenant_id = NEW.apprenant_id
      AND a.exam_id = v_exam
      AND a.consumed_at IS NULL
      AND a.revoked_at IS NULL
    ORDER BY a.created_at ASC
    LIMIT 1;

    IF v_auth IS NOT NULL THEN
      UPDATE public.exam_retake_authorizations
         SET consumed_at = now()
       WHERE id = v_auth;
      RETURN NEW;
    END IF;

    RAISE EXCEPTION 'EXAM_RETAKE_DELAY_48H: nouvelle tentative possible le %',
      to_char((v_last + interval '48 hours') AT TIME ZONE 'Europe/Paris', 'DD/MM/YYYY HH24"h"MI')
      USING ERRCODE = 'P0471';
  END IF;

  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.core_enforce_answer_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  att public.exam_attempts_v2%ROWTYPE;
BEGIN
  SELECT * INTO att FROM public.exam_attempts_v2 WHERE attempt_id = NEW.attempt_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ATTEMPT_INTROUVABLE: tentative % inexistante.', NEW.attempt_id
      USING ERRCODE = 'P0477';
  END IF;

  IF NEW.apprenant_id IS DISTINCT FROM att.apprenant_id THEN
    RAISE EXCEPTION 'ANSWER_OWNERSHIP: la reponse (apprenant %) n''appartient pas au proprietaire de la tentative (apprenant %).',
      NEW.apprenant_id, att.apprenant_id
      USING ERRCODE = 'P0477';
  END IF;

  PERFORM public.core_assert_session_owner(att.apprenant_id);

  IF att.etat <> 'en_cours' THEN
    RAISE EXCEPTION 'ATTEMPT_CLOSED: la tentative % est % : aucune reponse ne peut plus etre ecrite.', att.attempt_id, att.etat
      USING ERRCODE = 'P0478';
  END IF;

  IF NOT public.core_snapshot_has_question(att.snapshot, NEW.question_id) THEN
    RAISE EXCEPTION 'QUESTION_HORS_SNAPSHOT: la question % ne fait pas partie du snapshot de la tentative % (examen %).',
      NEW.question_id, att.attempt_id, att.exam_id
      USING ERRCODE = 'P0479';
  END IF;

  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.core_reponse_qrc_vide(p jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT p IS NULL
      OR jsonb_typeof(p) = 'null'
      OR (jsonb_typeof(p) = 'string' AND btrim(p #>> '{}', E' \t\r\n') = '')
      OR (jsonb_typeof(p) = 'array' AND jsonb_array_length(p) = 0)
      OR (jsonb_typeof(p) = 'object' AND p = '{}'::jsonb)
$function$
