CREATE OR REPLACE FUNCTION public.core_finalize_attempt(p_operation_id uuid, p_attempt_id uuid, p_qrc_questions text[] DEFAULT '{}'::text[], p_resultat jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rejeu jsonb;
  att public.exam_attempts_v2%ROWTYPE;
  qid text;
  nb_qrc integer := 0;
  nb_vides integer := 0;
  resultat jsonb;
  v_elearning boolean;
  v_valeur jsonb;
  v_trace boolean;
  v_inst uuid;
BEGIN
  rejeu := public.core_operation_replay(p_operation_id, 'attempt_finalize');
  IF rejeu IS NOT NULL THEN
    RETURN rejeu #> '{resultat}';
  END IF;

  SELECT * INTO att FROM public.exam_attempts_v2 WHERE attempt_id = p_attempt_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ATTEMPT_INTROUVABLE: tentative % inexistante.', p_attempt_id USING ERRCODE = 'P0477';
  END IF;

  IF att.etat <> 'en_cours' THEN
    RAISE EXCEPTION 'ATTEMPT_CLOSED: la tentative % est deja %.', p_attempt_id, att.etat USING ERRCODE = 'P0478';
  END IF;

  SELECT public.core_est_elearning(a.type_apprenant) INTO v_elearning
  FROM public.apprenants a WHERE a.id = att.apprenant_id;
  v_elearning := coalesce(v_elearning, false)
    AND NOT EXISTS (SELECT 1 FROM public.core_tentatives_neutralisees n WHERE n.attempt_id = p_attempt_id);

  FOREACH qid IN ARRAY coalesce(p_qrc_questions, '{}'::text[]) LOOP
    IF NOT public.core_snapshot_has_question(att.snapshot, qid) THEN
      RAISE EXCEPTION 'QUESTION_HORS_SNAPSHOT: la question % ne fait pas partie du snapshot de la tentative % (examen %).',
        qid, att.attempt_id, att.exam_id
        USING ERRCODE = 'P0479';
    END IF;

    v_valeur := (SELECT valeur FROM public.answer_state WHERE attempt_id = p_attempt_id AND question_id = qid);
    v_inst := NULL;

    INSERT INTO public.qrc_instances_v2 (attempt_id, question_id, apprenant_id, reponse, etat)
    VALUES (p_attempt_id, qid, att.apprenant_id, v_valeur, 'en_attente')
    ON CONFLICT (attempt_id, question_id) DO NOTHING
    RETURNING qrc_instance_id INTO v_inst;
    nb_qrc := nb_qrc + 1;

    -- 0 automatique : e-learning, instance créée maintenant, réponse vide, et
    -- aucune trace d'une réponse non vide dans l'historique (réponse perdue => pas de 0).
    IF v_elearning AND v_inst IS NOT NULL AND public.core_reponse_qrc_vide(v_valeur) THEN
      SELECT EXISTS (
        SELECT 1 FROM public.answer_events e
        WHERE e.attempt_id = p_attempt_id AND e.question_id = qid
          AND (NOT public.core_reponse_qrc_vide(e.valeur_nouvelle) OR NOT public.core_reponse_qrc_vide(e.valeur_precedente))
      ) INTO v_trace;
      IF NOT v_trace THEN
        PERFORM set_config('core.qrc_commentaire', 'QRC laissée sans réponse', true);
        PERFORM set_config('core.qrc_operation_id', p_operation_id::text, true);
        UPDATE public.qrc_instances_v2
        SET etat = 'corrigee', note = 0, corrige_par = NULL, corrige_email = 'auto:qrc_sans_reponse', corrige_at = now()
        WHERE qrc_instance_id = v_inst AND etat = 'en_attente';
        PERFORM set_config('core.qrc_commentaire', '', true);
        PERFORM set_config('core.qrc_operation_id', '', true);
        nb_vides := nb_vides + 1;
      END IF;
    END IF;
  END LOOP;

  UPDATE public.exam_attempts_v2
  SET etat = 'terminee', finished_at = now()
  WHERE attempt_id = p_attempt_id;

  resultat := jsonb_build_object('attempt_id', p_attempt_id, 'etat', 'terminee', 'qrc_creees', nb_qrc,
                                 'qrc_sans_reponse_zero', nb_vides, 'resultat', p_resultat);

  INSERT INTO public.core_operations (operation_id, operation_type, apprenant_id, attempt_id, auteur, cible, resultat)
  VALUES (p_operation_id, 'attempt_finalize', att.apprenant_id, p_attempt_id, auth.uid(),
          jsonb_build_object('qrc_questions', to_jsonb(p_qrc_questions)), resultat);

  INSERT INTO public.audit_journal (operation, cible_type, cible_id, exam_id, exam_version_id, attempt_id, apprenant_id, auteur, apres, origine)
  VALUES ('attempt_finalize', 'exam_attempts_v2', p_attempt_id::text, att.exam_id, att.exam_version_id, p_attempt_id, att.apprenant_id, auth.uid(), resultat, 'core_finalize_attempt');

  RETURN resultat;
END;
$function$
CREATE OR REPLACE FUNCTION public.start_or_get_exam_timer(_apprenant_id uuid, _exercice_id text, _duree_secondes integer, _tentative integer)
 RETURNS TABLE(started_at timestamp with time zone, server_now timestamp with time zone, duree_secondes integer, remaining_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.apprenant_examen_timers%ROWTYPE;
  v_is_owner boolean;
  v_tentative integer := GREATEST(1, COALESCE(_tentative, 1));
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM public.apprenants a
    WHERE a.id = _apprenant_id
      AND (a.id = auth.uid() OR a.auth_user_id = auth.uid())
  ) INTO v_is_owner;

  IF NOT (v_is_owner OR public.has_role(auth.uid(), 'admin')) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF _duree_secondes IS NULL OR _duree_secondes <= 0 THEN
    RAISE EXCEPTION 'invalid_duration';
  END IF;

  INSERT INTO public.apprenant_examen_timers (apprenant_id, user_id, exercice_id, duree_secondes, tentative)
  VALUES (_apprenant_id, auth.uid(), _exercice_id, _duree_secondes, v_tentative)
  ON CONFLICT (apprenant_id, exercice_id, tentative) DO NOTHING;

  SELECT * INTO v_row
  FROM public.apprenant_examen_timers
  WHERE apprenant_id = _apprenant_id
    AND exercice_id = _exercice_id
    AND tentative = v_tentative;

  RETURN QUERY
  SELECT
    v_row.started_at,
    clock_timestamp(),
    v_row.duree_secondes,
    GREATEST(0, v_row.duree_secondes - FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_row.started_at))))::integer;
END;
$function$
CREATE OR REPLACE FUNCTION public.core_save_answer(p_operation_id uuid, p_attempt_id uuid, p_question_id text, p_valeur jsonb, p_expected_revision integer, p_session_origine text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rejeu jsonb;
  att public.exam_attempts_v2%ROWTYPE;
  courant public.answer_state%ROWTYPE;
  resultat jsonb;
BEGIN
  rejeu := public.core_operation_replay(p_operation_id, 'answer_save');
  IF rejeu IS NOT NULL THEN
    RETURN rejeu #> '{resultat}';
  END IF;

  SELECT * INTO att FROM public.exam_attempts_v2 WHERE attempt_id = p_attempt_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ATTEMPT_INTROUVABLE: tentative % inexistante.', p_attempt_id USING ERRCODE = 'P0477';
  END IF;

  SELECT * INTO courant FROM public.answer_state
  WHERE attempt_id = p_attempt_id AND question_id = p_question_id FOR UPDATE;

  IF NOT FOUND THEN
    IF coalesce(p_expected_revision, 0) <> 0 THEN
      RAISE EXCEPTION 'ANSWER_STALE_REVISION: revision attendue % alors qu''aucune reponse n''existe.', p_expected_revision
        USING ERRCODE = 'P0409';
    END IF;

    INSERT INTO public.answer_state (attempt_id, apprenant_id, question_id, valeur, revision, updated_by, session_origine)
    VALUES (p_attempt_id, att.apprenant_id, p_question_id, p_valeur, 1, auth.uid(), p_session_origine)
    RETURNING * INTO courant;
  ELSE
    IF p_expected_revision IS NULL AND courant.valeur = p_valeur THEN
      resultat := jsonb_build_object(
        'response_id', courant.response_id,
        'attempt_id', courant.attempt_id,
        'question_id', courant.question_id,
        'revision', courant.revision
      );

      INSERT INTO public.core_operations (operation_id, operation_type, apprenant_id, attempt_id, auteur, cible, resultat)
      VALUES (p_operation_id, 'answer_save', att.apprenant_id, p_attempt_id, auth.uid(),
              jsonb_build_object('question_id', p_question_id, 'identical_retry', true), resultat);

      RETURN resultat;
    END IF;

    IF p_expected_revision IS DISTINCT FROM courant.revision THEN
      RAISE EXCEPTION 'ANSWER_STALE_REVISION: revision % obsolete (serveur = %).', p_expected_revision, courant.revision
        USING ERRCODE = 'P0409';
    END IF;

    UPDATE public.answer_state
    SET valeur = p_valeur,
        revision = courant.revision + 1,
        updated_by = auth.uid(),
        session_origine = p_session_origine
    WHERE response_id = courant.response_id
    RETURNING * INTO courant;
  END IF;

  resultat := jsonb_build_object(
    'response_id', courant.response_id,
    'attempt_id', courant.attempt_id,
    'question_id', courant.question_id,
    'revision', courant.revision
  );

  INSERT INTO public.core_operations (operation_id, operation_type, apprenant_id, attempt_id, auteur, cible, resultat)
  VALUES (p_operation_id, 'answer_save', att.apprenant_id, p_attempt_id, auth.uid(),
          jsonb_build_object('question_id', p_question_id), resultat);

  RETURN resultat;
END;
$function$
CREATE OR REPLACE FUNCTION public.garde_eb_legacy_cloture_vide()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_terminal boolean := (COALESCE(NEW.completed, false) OR NEW.status = 'submitted');
BEGIN
  -- Portée exacte : examens blancs legacy (le nouveau moteur n'écrit pas ici).
  IF NEW.exercice_type IS DISTINCT FROM 'examen_blanc' OR NEW.source_noyau IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NOT v_terminal OR public.eb_reponses_renseignees(NEW.reponses) THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    -- Ligne déjà terminée (historique) : jamais bloquée ici.
    IF COALESCE(OLD.completed, false) OR OLD.status = 'submitted' THEN
      RETURN NEW;
    END IF;
  END IF;
  RAISE EXCEPTION 'Clôture refusée : examen blanc % sans aucune réponse enregistrée. Rechargez normalement la page et attendez le chargement de vos réponses ; aucune donnée n''est supprimée.', NEW.exercice_id
    USING ERRCODE = 'P0530',
          HINT = 'EB_CLOTURE_VIDE_REFUSEE';
END;
$function$
CREATE OR REPLACE FUNCTION public.core_est_elearning(p_type text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(btrim(lower(p_type)), '') <> ''
     AND (lower(p_type) LIKE '%e-learning%' OR lower(p_type) LIKE '%elearning%'
          OR lower(btrim(p_type)) ~ '(^|[\s-])[a-z]{2,4}-e($|-)' OR lower(btrim(p_type)) LIKE '%-e')
$function$
CREATE OR REPLACE FUNCTION public.protect_reponses_apprenants_terminal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.completed = true AND NEW.status <> 'submitted' THEN
      NEW.status := 'submitted';
    END IF;
    IF NEW.status = 'submitted' THEN
      NEW.completed := true;
      NEW.submitted_at := COALESCE(NEW.submitted_at, now());
    END IF;
    RETURN NEW;
  END IF;

  -- Nouvelle tentative explicitement demandée : archiver puis repartir à zéro
  IF COALESCE(NEW.tentative, OLD.tentative) > OLD.tentative THEN
    IF OLD.status = 'submitted' THEN
      INSERT INTO public.reponses_apprenants_historique (
        apprenant_id, user_id, exercice_id, exercice_type, tentative,
        reponses, score, bonnes_reponses, total_questions, status, submitted_at
      ) VALUES (
        OLD.apprenant_id, OLD.user_id, OLD.exercice_id, OLD.exercice_type, OLD.tentative,
        OLD.reponses, OLD.score, OLD.bonnes_reponses, OLD.total_questions, OLD.status, OLD.submitted_at
      );
    END IF;
    NEW.status := 'in_progress';
    NEW.completed := false;
    NEW.submitted_at := NULL;
    NEW.score := NULL;
    NEW.bonnes_reponses := NULL;
    NEW.total_questions := NULL;
    NEW.reponses := '{}'::jsonb;
    RETURN NEW;
  END IF;

  IF OLD.status = 'submitted' THEN
    NEW.status := 'submitted';
    NEW.completed := true;
    NEW.submitted_at := COALESCE(NEW.submitted_at, OLD.submitted_at, now());
    NEW.score := COALESCE(NEW.score, OLD.score);
    NEW.bonnes_reponses := COALESCE(NEW.bonnes_reponses, OLD.bonnes_reponses);
    NEW.total_questions := COALESCE(NEW.total_questions, OLD.total_questions);
    NEW.tentative := GREATEST(COALESCE(NEW.tentative, 1), OLD.tentative);
    IF NEW.reponses IS NULL OR NEW.reponses = '{}'::jsonb THEN
      NEW.reponses := OLD.reponses;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.completed = true AND NEW.status <> 'submitted' THEN
    NEW.status := 'submitted';
  END IF;
  IF NEW.status = 'submitted' THEN
    NEW.completed := true;
    NEW.submitted_at := COALESCE(NEW.submitted_at, now());
  END IF;
  NEW.tentative := GREATEST(COALESCE(NEW.tentative, 1), OLD.tentative);
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.ensure_quiz_result_on_matiere_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_quiz_id text;
  v_matiere_raw text;
  v_matiere text;
  v_tentative integer := 1;
  v_exists boolean;
  v_apprenant_exists boolean;
  m text[];
  t text[];
  v_retake_tentative integer;
BEGIN
  IF NEW.exercice_type IS DISTINCT FROM 'examen_blanc' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.completed, false) <> true THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND COALESCE(OLD.completed, false) = true THEN
    RETURN NEW;
  END IF;

  m := regexp_match(NEW.exercice_id, '^((?:EB|eb)\d+(?:-[a-zA-Z0-9]+)?|bilan-[^_]+)_+(.+)$');
  IF m IS NULL THEN
    INSERT INTO public.alertes_systeme (type, titre, message, details)
    VALUES (
      'exam_result_missing',
      'Format exercice_id inconnu (examen blanc)',
      'Impossible de rattacher la matière terminée pour exercice_id=' || NEW.exercice_id,
      jsonb_build_object(
        'apprenant_id', NEW.apprenant_id,
        'exercice_id', NEW.exercice_id,
        'user_id', NEW.user_id
      )::text
    );
    RETURN NEW;
  END IF;

  v_quiz_id := m[1];
  v_matiere_raw := m[2];

  t := regexp_match(v_matiere_raw, '^(.+?)_+t(\d+)$');
  IF t IS NOT NULL THEN
    v_matiere := t[1];
    v_tentative := GREATEST(1, t[2]::integer);
  ELSE
    v_matiere := v_matiere_raw;
    v_tentative := 1;
  END IF;

  SELECT EXISTS(SELECT 1 FROM public.apprenants WHERE id = NEW.apprenant_id) INTO v_apprenant_exists;
  IF NOT v_apprenant_exists THEN
    RETURN NEW;
  END IF;

  -- Additive: an explicit subject-retake receipt binds this copy to ONE exact tentative.
  -- Earlier tentatives are never touched; legacy copies without receipt keep the code below.
  SELECT r.tentative INTO v_retake_tentative FROM public.exam_subject_retakes r
   WHERE r.apprenant_id = NEW.apprenant_id AND r.exercice_id = NEW.exercice_id;
  IF FOUND THEN
    UPDATE public.apprenant_quiz_results
       SET details = COALESCE(details, '{}'::jsonb)
                     || jsonb_build_object(
                          'auto_ensured_at', now(),
                          'source_exercice_id', NEW.exercice_id,
                          'source_tentative', v_retake_tentative,
                          'last_raw_reponses', COALESCE(NEW.reponses, '{}'::jsonb)
                        )
     WHERE apprenant_id = NEW.apprenant_id
       AND quiz_id = v_quiz_id
       AND COALESCE(matiere_id, '') = COALESCE(v_matiere, '')
       AND tentative = v_retake_tentative;
    IF NOT FOUND THEN
      INSERT INTO public.alertes_systeme (type, titre, message, details)
      VALUES ('exam_result_missing',
        'Matière refaite terminée sans note enregistrée (finalisation en attente)',
        'Les réponses sont conservées pour ' || NEW.exercice_id || ' : aucune autre tentative n''a été modifiée.',
        jsonb_build_object('apprenant_id', NEW.apprenant_id, 'quiz_id', v_quiz_id, 'matiere_id', v_matiere,
          'tentative', v_retake_tentative, 'exercice_id', NEW.exercice_id)::text);
    END IF;
    RETURN NEW;
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.apprenant_quiz_results
    WHERE apprenant_id = NEW.apprenant_id
      AND quiz_id = v_quiz_id
      AND COALESCE(matiere_id, '') = COALESCE(v_matiere, '')
  ) INTO v_exists;

  IF v_exists THEN
    -- Une note existe déjà : on ne touche ni au score, ni aux corrections.
    UPDATE public.apprenant_quiz_results
       SET details = COALESCE(details, '{}'::jsonb)
                     || jsonb_build_object(
                          'auto_ensured_at', now(),
                          'source_exercice_id', NEW.exercice_id,
                          'source_tentative', v_tentative,
                          'last_raw_reponses', COALESCE(NEW.reponses, '{}'::jsonb)
                        )
     WHERE apprenant_id = NEW.apprenant_id
       AND quiz_id = v_quiz_id
       AND COALESCE(matiere_id, '') = COALESCE(v_matiere, '')
       AND tentative = (
         SELECT MAX(tentative) FROM public.apprenant_quiz_results
         WHERE apprenant_id = NEW.apprenant_id
           AND quiz_id = v_quiz_id
           AND COALESCE(matiere_id, '') = COALESCE(v_matiere, '')
       );
    RETURN NEW;
  END IF;

  -- Aucune note écrite : on signale, on ne crée AUCUN résultat à 0.
  INSERT INTO public.alertes_systeme (type, titre, message, details)
  VALUES (
    'exam_result_missing',
    'Matière terminée sans note enregistrée (finalisation en attente)',
    'Les réponses sont conservées pour ' || NEW.exercice_id || ' : la note doit être recalculée, aucun 0 n''a été enregistré.',
    jsonb_build_object(
      'apprenant_id', NEW.apprenant_id,
      'user_id', NEW.user_id,
      'quiz_id', v_quiz_id,
      'matiere_id', v_matiere,
      'tentative', v_tentative,
      'exercice_id', NEW.exercice_id,
      'raw_reponses', COALESCE(NEW.reponses, '{}'::jsonb)
    )::text
  );

  RETURN NEW;
END;
$function$

